def tools_token_count(text: str, model: str) -> int:
    try:
        enc = encoding_for_model(model)
        return len(enc.encode(text))
    except Exception:
        logger.warning(f"Failed to get token count for model {model}, fallback to length of text")
        return len(text)


def json_default(obj):
    return str(obj)

def tools_json_save(data: dict | list, path: str):
    with open(path, 'w', encoding='utf-8', errors='replace') as f:
        try:
            json.dump(data, f, indent=4, ensure_ascii=False, default=json_default)
        except Exception as e:
            print(f"Failed to save JSON to {path}: {e}, fallback to repair_json")
            data = repair_json(str(data), return_objects=True)
            json.dump(data, f, indent=4, ensure_ascii=False, default=json_default)


def normalize_azure_url(base_url: str) -> str:
    """Normalize Azure OpenAI base URLs to include /openai/v1 suffix.
    After normalization, we can directly use the OpenAI client to interact with the Azure OpenAI endpoint.
    """
    if "openai.azure.com" in base_url or "services.ai.azure.com" in base_url:
        stripped = base_url.rstrip("/")
        if not stripped.endswith("/openai/v1"):
            return stripped + "/openai/v1"
    return base_url


def resolve_llm_config(
    api_url_override: str | None = None,
    model_override: str | None = None,
    require_model: bool = False,
) -> tuple[str, str, str]:
    """Resolve LLM API URL, API key, and model from environment variables.

    Supports Azure OpenAI and standard OpenAI providers via env vars:
      - AWM_SYN_LLM_PROVIDER ("azure" | "openai")
      - AZURE_ENDPOINT_URL / AZURE_OPENAI_API_KEY  (for azure)
      - OPENAI_BASE_URL / OPENAI_API_KEY            (for openai)
      - AWM_SYN_OVERRIDE_MODEL                       (model name)

    Args:
        api_url_override: if given, used directly as base_url (still normalized for Azure).
        model_override: if given, used instead of AWM_SYN_OVERRIDE_MODEL env var.
        require_model: if True, raises ValueError when no model can be resolved.

    Returns:
        (api_url, api_key, model)
    """
    provider = os.environ.get("AWM_SYN_LLM_PROVIDER", "").lower()

    # --- resolve base URL ---
    if api_url_override:
        api_url = normalize_azure_url(api_url_override)
    elif provider == "azure":
        azure_endpoint = os.environ.get("AZURE_ENDPOINT_URL", "")
        if not azure_endpoint:
            raise ValueError(
                "AZURE_ENDPOINT_URL not set.\n"
                "Please set: AWM_SYN_LLM_PROVIDER, AZURE_ENDPOINT_URL, AZURE_OPENAI_API_KEY"
            )
        api_url = normalize_azure_url(azure_endpoint)
    elif os.environ.get("OPENAI_BASE_URL"):
        api_url = os.environ["OPENAI_BASE_URL"]
    else:
        raise ValueError("No LLM API URL provided.")

    # --- resolve API key ---
    if provider == "azure":
        api_key = os.environ.get("AZURE_OPENAI_API_KEY", "EMPTY")
    else:
        api_key = os.environ.get("OPENAI_API_KEY", "EMPTY")

"""
Verify agent run outputs.

Supports two verification modes:
- "sql": Run verifier code to extract DB state info, then use LLM to judge. This mode is recommended for most cases.
- "code": Run verifier code that deterministically returns "complete" or "others".
"""

import inspect
import json
import os
import re
import sqlite3
import asyncio
import httpx
from dataclasses import dataclass
from textwrap import dedent
from enum import Enum

from loguru import logger
from openai import AsyncOpenAI

from awm.tools import (
    tools_jsonl_load,
    tools_json_save,
    normalize_azure_url,
    resolve_llm_config,
    sanitize_for_json,
    find_scenario_entry,
)


class VerificationMode(Enum):
    sql = "sql"  # code-augmented verification (returns info dict for LLM judgment)
    code = "code" # purely code-based verification (returns complete/others)

@dataclass
class Config:
    # Path to the agent run output directory (contains trajectory.json, initial.db, final.db)
    input: str
    # optional, path to the initial database path, if specified, will override the input
    init_db_path: str | None = None
    # optional, path to the final database path, if specified, will override the input
    final_db_path: str | None = None
    # Verification mode: "sql" or "code", sql mode is the recommended code-augmented LLM-as-a-Judge mode.
    mode: VerificationMode = VerificationMode.sql
    # Path to verifier data file (sql mode). Defaults to outputs/gen_verifier.jsonl
    verifier_path: str | None = None
    # Path to verifier data file (code mode). Defaults to outputs/gen_verifier.pure_code.jsonl
    verifier_code_path: str | None = None

    def pre_process(self):
        if self.mode == VerificationMode.sql:
            # check llm environment variables
            provider = os.environ.get("AWM_SYN_LLM_PROVIDER", "").lower()
            if provider == "azure":
                missing = []
                if not os.environ.get("AZURE_ENDPOINT_URL"):
                    missing.append("AZURE_ENDPOINT_URL")
                if not os.environ.get("AZURE_OPENAI_API_KEY"):
                    missing.append("AZURE_OPENAI_API_KEY")
                if missing:
                    raise ValueError(
                        f"SQL verification mode requires Azure LLM config. Missing env vars: {', '.join(missing)}.\n"
                        "Please set: AWM_SYN_LLM_PROVIDER=azure, AZURE_ENDPOINT_URL, AZURE_OPENAI_API_KEY"
                    )
            else:
                if not os.environ.get("OPENAI_API_KEY") and not os.environ.get("OPENAI_BASE_URL"):
                    raise ValueError(
                        "SQL verification mode requires LLM config. Missing env vars.\n"
                        "Please set either:\n"
                        "  - AWM_SYN_LLM_PROVIDER=azure + AZURE_ENDPOINT_URL + AZURE_OPENAI_API_KEY\n"
                        "  - OPENAI_API_KEY (+ optional OPENAI_BASE_URL)"
                    )
            if not os.environ.get("AWM_SYN_OVERRIDE_MODEL"):
                raise ValueError(
                    "SQL verification mode requires AWM_SYN_OVERRIDE_MODEL to be set.\n"
                    "Example: export AWM_SYN_OVERRIDE_MODEL=gpt-5"
                )



def _call_verifier_func(verify_func, initial_db_path, final_db_path, final_answer=None):
    """Call a verifier function with signature-aware argument passing."""
    sig = inspect.signature(verify_func)
    params = sig.parameters

    kwargs = {}
    if "initial_db_path" in params:
        kwargs["initial_db_path"] = initial_db_path
    if "final_db_path" in params:
        kwargs["final_db_path"] = final_db_path
    if "final_answer" in params:
        kwargs["final_answer"] = final_answer or ""

    if not kwargs and len(params) >= 2:
        args = [initial_db_path, final_db_path]
        if len(params) >= 3:
            args.append(final_answer or "")
        return verify_func(*args)

    return verify_func(**kwargs)


def execute_sql_verifier(verifier_code, function_name, initial_db_path, final_db_path):
    """Execute SQL-mode verifier code that compares initial vs final DB state."""
    if not os.path.exists(initial_db_path):
        return {"execution_status": "error", "error_message": f"Initial DB not found: {initial_db_path}"}
    if not os.path.exists(final_db_path):
        return {"execution_status": "error", "error_message": f"Final DB not found: {final_db_path}"}

    original_modes = {}
    for path in [initial_db_path, final_db_path]:
        try:
            original_modes[path] = os.stat(path).st_mode
            os.chmod(path, 0o444)
        except Exception:
            pass

    try:
        namespace = {
            "sqlite3": sqlite3,
            "json": json,
            "os": os,
            "__builtins__": __builtins__,
        }
        exec(verifier_code, namespace)

        verify_func = namespace.get(function_name)
        if not verify_func:
            return {"execution_status": "error", "error_message": f"Function '{function_name}' not found"}

        result = _call_verifier_func(verify_func, initial_db_path, final_db_path)

        try:
            json.dumps(result)
        except TypeError:
            result = sanitize_for_json(result)

        return result

    except Exception as e:
        return {"execution_status": "error", "error_message": f"Execution error: {e}"}
    finally:
        for path, mode in original_modes.items():
            try:
                os.chmod(path, mode)
            except Exception:
                pass


def execute_code_verifier(verifier_code, function_name, initial_db_path, final_db_path, final_answer=None):
    """Execute code-mode verifier that returns {"result": "complete"|"others"}."""
    if not os.path.exists(initial_db_path):
        return {"result": "others", "execution_status": "error", "error_message": f"Initial DB not found: {initial_db_path}"}
    if not os.path.exists(final_db_path):
        return {"result": "others", "execution_status": "error", "error_message": f"Final DB not found: {final_db_path}"}

    original_modes = {}
    for path in [initial_db_path, final_db_path]:
        try:
            original_modes[path] = os.stat(path).st_mode
            os.chmod(path, 0o444)
        except Exception:
            pass

    try:
        namespace = {
            "sqlite3": sqlite3,
            "json": json,
            "os": os,
            "re": re,
            "__builtins__": __builtins__,
        }
        exec(verifier_code, namespace)

        verify_func = namespace.get(function_name)
        if not verify_func:
            return {"result": "others", "execution_status": "error", "error_message": f"Function '{function_name}' not found"}

        result = _call_verifier_func(verify_func, initial_db_path, final_db_path, final_answer)

        if not isinstance(result, dict) or "result" not in result:
            return {"result": "others", "execution_status": "error", "error_message": f"Invalid return format: {type(result).__name__}"}

        result_value = result.get("result", "others")
        if result_value not in ("complete", "others"):
            result_value = "others"

        return {"result": result_value, "execution_status": "success", "raw_result": result}

    except Exception as e:
        return {"result": "others", "execution_status": "error", "error_message": f"Execution error: {e}"}
    finally:
        for path, mode in original_modes.items():
            try:
                os.chmod(path, mode)
            except Exception:
                pass


def run_verifier(verifier_entry, verifier_mode, initial_db_path, final_db_path, final_answer=None):
    """Run the appropriate verifier and return (reward_type, details)."""
    verification = verifier_entry.get("verification", {})
    code = verification.get("code", "")

    if not code or not isinstance(code, str) or len(code.strip()) < 10:
        return "judge_error", {"error": "No valid verifier code found"}

    default_func = "verify_task_completion" if verifier_mode == "code" else "verify_task"
    func_name = default_func
    for line in code.split("\n"):
        line = line.strip()
        if line.startswith("def verify_") and "(" in line:
            func_name = line.split("(")[0].replace("def ", "").strip()
            break

    if verifier_mode == "code":
        result = execute_code_verifier(code, func_name, initial_db_path, final_db_path, final_answer)
        if result.get("execution_status") == "error":
            return "judge_error", result
        return result.get("result", "others"), result

    result = execute_sql_verifier(code, func_name, initial_db_path, final_db_path)
    if isinstance(result, dict) and result.get("execution_status") == "error":
        return "judge_error", result

    return "incomplete", result


async def run_llm_judge(task, verifier_result, llm_base_url, llm_api_key, llm_model, trajectory=None):
    """Run LLM-as-a-judge combining agent trajectory AND SQL verification results."""
    if not llm_base_url or not llm_model:
        return "judge_error", {"error": "LLM endpoint not configured for sql verifier mode"}

    llm_base_url = normalize_azure_url(llm_base_url)

    try:
        # Hosted judges can take longer than the SDK's connect/read defaults,
        # and inherited proxy settings are often unreliable on training nodes.
        timeout = float(os.environ.get("AWM_JUDGE_TIMEOUT", "120"))
        max_retries = max(0, int(os.environ.get("AWM_JUDGE_MAX_RETRIES", "3")))
        http_client = httpx.AsyncClient(timeout=timeout, trust_env=False)
        client = AsyncOpenAI(
            base_url=llm_base_url,
            api_key=llm_api_key or "EMPTY",
            timeout=timeout,
            max_retries=max_retries,
            http_client=http_client,
        )

        system_prompt = dedent("""\
            You are an impartial evaluator of automated agent task results with access to database verification. Based on the provided JSON trajectory AND the Python verification results from querying the database, decide the task outcome. This trajectory is generated by an MCP agent on a simulated simplified environment. The environment provides a set of MCP tools to help the agent complete the task.

            Input:
                task_json: dict containing task fields such as user task and agent execution_history.
                verification_json: dict containing Python code, reasoning, success_criteria, failure_criteria, and execution results that verified the database state from the Python function

            Output:
                You only output UTF-8 encoded string, avoid any emoji or special characters. You only output English text.
from dataclasses import dataclass
import os
import shutil
import subprocess
import sys
import textwrap
from datetime import datetime
from loguru import logger

from awm.tools import tools_jsonl_load, normalize_scenario_name
from awm.core.reset import reset_single_database

@dataclass
class Config:
    scenario: str
    envs_load_path: str # specify a path to load generated_envs.jsonl
    db_path: str | None = None # specify a path to load the database file, xxx.db
    host: str = "127.0.0.1"
    port: int = 8001
    temp_server_path: str | None = None # specify a temp server path, the code will be written to this path
    # Path to generated db schemas file (used when db_path is None to create DB from schema)
    db_schema_path: str = "./outputs/gen_db.jsonl"
    # Path to generated sample data file (used when db_path is None)
    sample_path: str = "./outputs/gen_sample.jsonl"
    # Output directory for server artifacts. Auto-created if not specified.
    output_dir: str | None = None

    def pre_process(self):
        self.scenario = normalize_scenario_name(self.scenario)
        assert os.path.exists(self.envs_load_path), f"Environment file {self.envs_load_path} not found"


def format_raw_code_to_lines(raw_code: str, indent: int) -> list[str]:
    no_indent_code = textwrap.dedent(raw_code).strip()
    indent_code = textwrap.indent(no_indent_code, ' ' * indent)
    return indent_code.split("\n")


def _prepare_server_dir(config: Config) -> str:
    """Prepare the server output directory.

    Creates outputs/servers/<timestamp>_<scenario> if output_dir is not set.
    Returns the output directory path.
    """
    if config.output_dir:
        output_dir = config.output_dir
    else:
        timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
        output_dir = os.path.join("outputs", "servers", f"{timestamp}_{config.scenario}")
    os.makedirs(output_dir, exist_ok=True)
    return output_dir


def _prepare_database(config: Config, output_dir: str) -> str:
    """Prepare the database for the server.

    If db_path is specified, uses it directly.
    Otherwise, creates a fresh DB via reset_single_database.
    Saves a copy as initial.db in the output directory.

    Returns the path to the working database file.
    """
    if config.db_path:
        db_file_path = config.db_path
        assert os.path.exists(db_file_path), f"Database file {db_file_path} not found"
        # Save initial DB snapshot
        initial_db_path = os.path.join(output_dir, "initial.db")
        shutil.copy2(db_file_path, initial_db_path)
        logger.info(f"Saved initial database to {initial_db_path}")
    else:
        # Create DB directly in output_dir as final.db (the working copy)
        db_file_path = reset_single_database(
            input_db=config.db_schema_path,
            input_sample=config.sample_path,
            scenario=config.scenario,
            database_dir=output_dir,
        )
        # reset_single_database names it <scenario>.db, rename to final.db
        final_db_path = os.path.join(output_dir, "final.db")
        os.rename(db_file_path, final_db_path)
        db_file_path = final_db_path
        logger.info(f"Created database at {db_file_path}")

        # Save initial DB snapshot (copy of the freshly created DB)
        initial_db_path = os.path.join(output_dir, "initial.db")
        shutil.copy2(db_file_path, initial_db_path)
        logger.info(f"Saved initial database to {initial_db_path}")

    return db_file_path


def _generate_server_code(config: Config, db_path: str) -> str:
    """Generate the MCP server code and write it to a file.

    Returns the path to the generated server code file.
    """
    envs = tools_jsonl_load(config.envs_load_path)
    envs = {normalize_scenario_name(e["scenario"]): e for e in envs}
    env = envs[config.scenario]

    code = env["full_code"]

    # Generated APIs should be safe to retry.  In particular, the mentoring
    # benchmark seeds the requested cohort in the initial database; a model
    # may therefore call create_program even though the row already exists.
    # The generated endpoint historically inserted blindly and surfaced the
    # UNIQUE(cohort_name) violation as an opaque MCP 500.  Make this endpoint
    # idempotent at generation time: return an existing row with the same
    # cohort name before attempting the insert.
    create_program_insert = (
        "    program = Program(cohort_name=body.cohort_name, start_date=start_date_obj, "
        "end_date=end_date_obj, target_audience=body.target_audience, "
        "max_participants=body.max_participants, created_by_user_id=CURRENT_USER_ID, "
        "created_at=now, updated_at=now)\n"
        "    session.add(program)"
    )
    create_program_idempotent = (
        "    existing = session.query(Program).filter(Program.cohort_name == body.cohort_name).first()\n"
        "    if existing is not None:\n"
        "        if (existing.start_date != start_date_obj or existing.end_date != end_date_obj "
        "or existing.target_audience != body.target_audience or existing.max_participants != body.max_participants):\n"
        "            session.close()\n"
        "            raise HTTPException(status_code=409, detail='A program with this cohort_name already exists with different fields')\n"
        "        result = ProgramResponse(id=existing.id, cohort_name=existing.cohort_name, "
        "start_date_value=existing.start_date, end_date_value=existing.end_date, "
        "target_audience=existing.target_audience, max_participants=existing.max_participants, "
        "created_by_user_id=existing.created_by_user_id, created_at=existing.created_at, "
        "updated_at=existing.updated_at)\n"
        "        session.close()\n"
        "        return result\n"
        + create_program_insert
    )
    if create_program_insert in code:
        code = code.replace(create_program_insert, create_program_idempotent, 1)

    # Vaccine definitions are keyed by name.  Tool-call retries currently
    # turn a successful first create into repeated UNIQUE(name) violations.
    vaccine_insert = (
        "    db_obj = VaccineDefinition(\n"
        "        name=vd.name,\n"
        "        species=vd.species,\n"
        "        description=vd.description,\n"
        "        created_at=datetime.utcnow(),\n"
        "        updated_at=None,\n"
        "    )\n"
        "    session.add(db_obj)"
    )
    vaccine_idempotent = (
        "    existing = session.query(VaccineDefinition).filter(VaccineDefinition.name == vd.name).first()\n"
        "    if existing is not None:\n"
        "        if existing.species != vd.species or (vd.description is not None and existing.description != vd.description):\n"
        "            session.close()\n"
        "            raise HTTPException(status_code=409, detail='A vaccine definition with this name already exists with different fields')\n"
        "        resp = VaccineDefinitionResponse.from_orm(existing)\n"
        "        session.close()\n"
        "        return resp\n"
        + vaccine_insert
    )
    if vaccine_insert in code:
        code = code.replace(vaccine_insert, vaccine_idempotent, 1)

    new_code = [
        'import warnings',
        'warnings.filterwarnings("ignore", category=DeprecationWarning)',
        'from fastapi import HTTPException',
    ]
    for line in code.split("\n"):

        if 'create_engine(' in line:
            left = line.split('create_engine(')[0]
            sql_path = f"'sqlite:///{db_path}'"
            right = f"create_engine({sql_path}, connect_args={{'check_same_thread': False}})"
            line = f"{left}{right}"

        if 'uvicorn.run(app' in line:
            raw_code = f"""
            import os
            host = os.environ.get('HOST', '{config.host}')
            port = os.environ.get('PORT', {config.port})
            print(f'Server starting on port={{port}}')
            """
            lines = format_raw_code_to_lines(raw_code, indent=4)
            raw_code = f"""
            from fastapi_mcp import FastApiMCP
            mcp = FastApiMCP(app)
            mcp.mount_http()
            print("MCP server enabled, please visit http://{config.host}:{config.port}/mcp for the MCP service")
            """
            lines += format_raw_code_to_lines(raw_code, indent=4)

            line = '    uvicorn.run(app, host=host, port=int(port))'
            new_code.extend(lines)

        new_code.append(line)

    server_code = "\n".join(new_code)

    if config.temp_server_path is None:
        config.temp_server_path = os.path.join(
            os.path.dirname(config.envs_load_path),
            f"temp_server_{config.scenario.lower()}.py",
        )

    with open(config.temp_server_path, "w") as f:
        f.write(server_code)

    return config.temp_server_path


def run_server(config: Config):
    output_dir = _prepare_server_dir(config)
    db_path = _prepare_database(config, output_dir)
    server_code_path = _generate_server_code(config, db_path)

    # Save a copy of server code to output dir
    shutil.copy2(server_code_path, os.path.join(output_dir, "server_code.py"))

    logger.info(f"Server artifacts saved to {output_dir}")
    logger.info(f"Starting server for {config.scenario} on {config.host}:{config.port}")

    os.environ['PORT'] = str(config.port)
    os.environ['DATABASE_PATH'] = f"sqlite:///{db_path}"

    # Run server and capture log
    log_path = os.path.join(output_dir, "server.log")
    logger.info(f"Server log will be saved to {log_path}")
    ret = os.system(f"{sys.executable} {server_code_path} 2>&1 | tee {log_path}")

    # After server exits, save final DB snapshot
    final_db_path = os.path.join(output_dir, "final.db")
    if os.path.exists(db_path):
        shutil.copy2(db_path, final_db_path)
        logger.info(f"Saved final database to {final_db_path}")

    return ret


def start_server_process(
    scenario: str,
    envs_load_path: str,
    db_path: str,
    port: int,
    output_dir: str | None = None,
    temp_server_path: str | None = None,
) -> subprocess.Popen:
    """Start MCP server as a background subprocess.

    Returns the Popen handle so the caller can manage the process lifecycle.
    """
    cmd = [
        sys.executable, "-m", "awm.core.server",
        "--scenario", scenario,
        "--envs_load_path", envs_load_path,
        "--db_path", db_path,
        "--port", str(port),
    ]
    if output_dir:
        cmd.extend(["--output_dir", output_dir])
    if temp_server_path:
        cmd.extend(["--temp_server_path", temp_server_path])
