               MAX(CASE WHEN sp.price_type = 'real_time' THEN sp.price END) as real_time,
               MAX(CASE WHEN sp.price_type = 'previous_close' THEN sp.price END) as prev_close
        FROM securities s
        JOIN security_prices sp ON s.id = sp.security_id
        WHERE s.symbol IN ('MSFT', 'GOOGL', 'NVDA', 'AMZN')
