{"scenario": "productivity_assistant_1", "task_idx": 2, "task": "Generate 10 diverse blog post ideas and corresponding SEO-friendly titles and meta descriptions for a small online bakery in Austin, Texas that specializes in gluten-free cupcakes and seasonal holiday cakes.", "verification": {"code": "def verify_task_completion(initial_db_path: str, final_db_path: str, final_answer: str | None = None) -> dict:\n    import sqlite3\n    import re\n\n    def safe_query(db_path: str, query: str, params: tuple = ()) -> list:\n        try:\n            conn = sqlite3.connect(f\"file:{db_path}?mode=ro\", uri=True)\n            cursor = conn.cursor()\n            cursor.execute(query, params)\n            results = cursor.fetchall()\n            conn.close()\n            return results\n        except Exception:\n            return []\n\n    # Check if a new content_generation_tasks record was created\n    initial_content_tasks = safe_query(initial_db_path, \"SELECT id, business_location, business_niche FROM content_generation_tasks\")\n    final_content_tasks = safe_query(final_db_path, \"SELECT id, business_location, business_niche FROM content_generation_tasks\")\n    \n    if len(final_content_tasks) <= len(initial_content_tasks):\n        return {\"result\": \"others\"}\n    \n    # Find the new content task(s)\n    initial_ids = set(task[0] for task in initial_content_tasks)\n    new_content_tasks = [task for task in final_content_tasks if task[0] not in initial_ids]\n    \n    if not new_content_tasks:\n        return {\"result\": \"others\"}\n    \n    # Check if any new task matches Austin and gluten-free context\n    austin_task_id = None\n    for task_id, location, niche in new_content_tasks:\n        if location and \"austin\" in location.lower() and \"texas\" in location.lower():\n            if niche and \"gluten\" in niche.lower() and \"cupcake\" in niche.lower():\n                austin_task_id = task_id\n                break\n    \n    if austin_task_id is None:\n        return {\"result\": \"others\"}\n    \n    # Check blog_post_ideas for this content task\n    initial_blog_ideas = safe_query(initial_db_path, \"SELECT id, content_task_id, position, idea_title, seo_title, meta_description FROM blog_post_ideas WHERE content_task_id = ?\", (austin_task_id,))\n    final_blog_ideas = safe_query(final_db_path, \"SELECT id, content_task_id, position, idea_title, seo_title, meta_description FROM blog_post_ideas WHERE content_task_id = ?\", (austin_task_id,))\n    \n    new_blog_ideas = [idea for idea in final_blog_ideas if idea[0] not in set(i[0] for i in initial_blog_ideas)]\n    \n    # Must have exactly 10 new blog ideas\n    if len(new_blog_ideas) != 10:\n        return {\"result\": \"others\"}\n    \n    # Verify each blog idea has all required fields populated\n    positions = set()\n    for idea_id, content_task_id, position, idea_title, seo_title, meta_description in new_blog_ideas:\n        # Check all required fields are non-empty\n        if not idea_title or not idea_title.strip():\n            return {\"result\": \"others\"}\n        if not seo_title or not seo_title.strip():\n            return {\"result\": \"others\"}\n        if not meta_description or not meta_description.strip():\n            return {\"result\": \"others\"}\n        \n        # Check position is in valid range\n        if position is None or position < 1 or position > 10:\n            return {\"result\": \"others\"}\n        \n        # Track positions to ensure uniqueness\n        if position in positions:\n            return {\"result\": \"others\"}\n        positions.add(position)\n    \n    # Verify we have all positions 1-10\n    if positions != set(range(1, 11)):\n        return {\"result\": \"others\"}\n    \n    # Verify contextual relevance - check if ideas contain relevant keywords\n    relevant_keywords = ['gluten', 'free', 'cupcake', 'cake', 'bakery', 'austin', 'dessert', 'holiday', 'seasonal']\n    relevant_count = 0\n    \n    for idea_id, content_task_id, position, idea_title, seo_title, meta_description in new_blog_ideas:\n        combined_text = f\"{idea_title} {seo_title} {meta_description}\".lower()\n        if any(keyword in combined_text for keyword in relevant_keywords):\n            relevant_count += 1\n    \n    # At least 8 out of 10 ideas should be contextually relevant\n    if relevant_count < 8:\n        return {\"result\": \"others\"}\n    \n    # All checks passed\n    return {\"result\": \"complete\"}", "raw_response": ""}}

