const r = await tools.exec_command({cmd:"python - <<'PY'
import json,collections
from pathlib import Path
# derive task mapping
T={}
for line in open('data/AgentWorldModel-1K/gen_tasks.jsonl'):
 r=json.loads(line)
 for i,t in enumerate(r['tasks']):T[t]=(r['scenario'],i)
for p in sorted(Path('logs/rollouts').glob('*.jsonl'),key=lambda p:int(p.stem)):
 by=collections.defaultdict(list)
 for l in p.open():
  r=json.loads(l);by[r['traj_uid']].append(r)
 print('\n===STEP',p.stem)
 for uid,rs in by.items():
  rs.sort(key=lambda x:x['step_num']); task=rs[0]['obs_text_base'].split('User task:\n')[-1].strip(); print('traj',uid,'scenario/task',T.get(task),'score',rs[-1]['score'],'rows',len(rs),'sample',rs[0]['sample_id'])
