def verify_task_completion(initial_db_path: str, final_db_path: str, final_answer: str | None = None) -> dict:
    import sqlite3
    import re

    def safe_query(db_path: str, query: str, params: tuple = ()) -> list:
        try:
            conn = sqlite3.connect(f"file:{db_path}?mode=ro", uri=True)
            cursor = conn.cursor()
            cursor.execute(query, params)
            results = cursor.fetchall()
            conn.close()
            return results
        except Exception:
            return []

    # Get all question IDs from initial state
    initial_questions = safe_query(initial_db_path, "SELECT id FROM questions")
    initial_question_ids = {row[0] for row in initial_questions}

    # Get all question IDs from final state
    final_questions = safe_query(final_db_path, "SELECT id FROM questions")
    final_question_ids = {row[0] for row in final_questions}

    # Find new questions
    new_question_ids = final_question_ids - initial_question_ids

    if not new_question_ids:
        return {"result": "others"}

    # Check each new question for the required title
    required_title = "How to fix TypeError: unsupported operand type(s) for +: int and str in Python?"

    for question_id in new_question_ids:
        question_data = safe_query(
            final_db_path,
            "SELECT title, body FROM questions WHERE id = ?",
            (question_id,)
        )

        if not question_data:
            continue

        title, body = question_data[0]

        # Check 1: Title must match exactly
        if title != required_title:
            continue

        # Check 2: Body must mention the error line with total = 5 + '3' or similar
        # Allow flexible whitespace and quote variations
        line_pattern = r"total\s*=\s*5\s*\+\s*['"]3['"]|"
        line_pattern += r"5\s*\+\s*['"]3['"]|" 
        line_pattern += r"total\s*=\s*5\s*\+\s*.3."

        if not re.search(line_pattern, body, re.IGNORECASE):
            continue

        # Check 3: Body must mention Python 3.11
        if not re.search(r"Python\s*3\.11|3\.11|python\s*3\.11", body, re.IGNORECASE):
            continue

        # Check 4: Body must contain code snippet indicators
        # Look for code markers like ```, backticks, or code block formatting
        code_indicators = ["```", "`", "    ", "\t"]
        has_code = any(indicator in body for indicator in code_indicators)
        if not has_code:
            continue

        # Check 5: Verify tags - must have exactly python, typeerror, and python-3.x
        tags_data = safe_query(
            final_db_path,
            """SELECT t.name FROM question_tags qt
               JOIN tags t ON qt.tag_id = t.id
               WHERE qt.question_id = ?""",
            (question_id,)
        )

        if not tags_data:
            continue

        tag_names = {row[0].lower() for row in tags_data}
        required_tags = {"python", "typeerror", "python-3.x"}

        # Must have exactly these three tags
        if tag_names == required_tags:
            return {"result": "complete"}

    return {"result": "others"}

### 9998 ticketing_and_access_management_1 5
def verify_task_completion(initial_db_path: str, final_db_path: str, final_answer: str | None = None) -> dict:
    import sqlite3
    import re

    def safe_query(db_path: str, query: str, params: tuple = ()) -> list:
        try:
            conn = sqlite3.connect(f"file:{db_path}?mode=ro", uri=True)
            cursor = conn.cursor()
            cursor.execute(query, params)
            results = cursor.fetchall()
            conn.close()
            return results
        except Exception:
            return []

    if not final_answer or len(final_answer.strip()) < 10:
        return {"result": "others"}

    # Step 1: Find user with active subscription to 'Indie Fridays Live'
    user_query = """
        SELECT cs.user_id 
        FROM channel_subscriptions cs
        JOIN channels c ON cs.channel_id = c.id
        WHERE c.title = 'Indie Fridays Live'
        AND cs.status = 'active'
        AND cs.start_at <= '2026-01-31 23:59:59'
        AND (cs.end_at IS NULL OR cs.end_at >= '2026-01-01 00:00:00')
    """
    user_results = safe_query(final_db_path, user_query)
    if not user_results:
        return {"result": "others"}

    user_id = user_results[0][0]
    if user_id != 2:
        return {"result": "others"}

    # Step 2: Get valid passes for this user in Jan 2026
    passes_query = """
        SELECT ap.id, ap.event_id, ap.access_type, ap.status
        FROM access_passes ap
        JOIN events e ON ap.event_id = e.id
        WHERE ap.user_id = ?
        AND e.start_time >= '2026-01-01 00:00:00'
        AND e.start_time <= '2026-01-31 23:59:59'
        AND ap.status IN ('active', 'scheduled')
        ORDER BY ap.event_id
    """
    passes = safe_query(final_db_path, passes_query, (user_id,))

    if not passes:
        return {"result": "others"}

    # Expected: access_passes id 1,6,8 for events 1,1,4
    expected_pass_ids = {1, 6, 8}
    expected_event_ids = {1, 4}

    actual_pass_ids = {p[0] for p in passes}
    actual_event_ids = {p[1] for p in passes}

    # Verify we have the correct passes
    if actual_pass_ids != expected_pass_ids:
        return {"result": "others"}

    if actual_event_ids != expected_event_ids:
        return {"result": "others"}

    # Step 3: Verify final_answer mentions both event IDs
    event_1_found = False
    event_4_found = False

    # Check for event 1 mentions
    if (re.search(r"event[_\s]*(?:id)?[:\s]*['"]?1['"]?", final_answer, re.IGNORECASE) or
        re.search(r"\bevent\s+1\b", final_answer, re.IGNORECASE)):
        event_1_found = True

    # Check for event 4 mentions
    if (re.search(r"event[_\s]*(?:id)?[:\s]*['"]?4['"]?", final_answer, re.IGNORECASE) or
        re.search(r"\bevent\s+4\b", final_answer, re.IGNORECASE)):
        event_4_found = True

    if not (event_1_found and event_4_found):
        return {"result": "others"}

    # Step 4: Check for grouping indication
    grouping_patterns = [
        r"group(?:ed)?\s+by\s+event",
        r"event[_\s]*(?:id)?[:\s]*1.*event[_\s]*(?:id)?[:\s]*4",
        r"for\s+event\s+(?:id\s+)?1",
        r"event\s+1[:\s]*.*event\s+4[:\s]*"
    ]

    grouping_found = any(re.search(pattern, final_answer, re.IGNORECASE) for pattern in grouping_patterns)

    if not grouping_found:
        return {"result": "others"}

    # Step 5: Verify pass details are mentioned (look for access_pass IDs or types)
    pass_detail_found = False

    # Check for pass IDs or subscription/ticket mentions
    if (re.search(r"\b[168]\b", final_answer) or
        re.search(r"subscription", final_answer, re.IGNORECASE) or
        re.search(r"ticket", final_answer, re.IGNORECASE)):
        pass_detail_found = True

    if not pass_detail_found:
        return {"result": "others"}

    # All checks passed
    return {"result": "complete"}
