        indexes = table.get("indexes", [])
        for idx in indexes:
            if not isinstance(idx, str):
                logger.warning(f"Invalid index: {idx}, type: {type(idx)}, force to string...")
                idx = str(idx)
            idx_stmt = idx.strip()
            if idx_stmt:
                parts.append(idx_stmt)
        if indexes:
            parts.append("")

    while parts and parts[-1] == "":
        parts.pop()

    return "\n".join(parts)


