import json,pathlib,ast,sqlite3,tempfile,collections
# Check stale-vs-latest rules on unchanged reconstructed states. No training or service startup.
root=pathlib.Path('.')
rows=[json.loads(l) for l in (root/'data/AgentWorldModel-1K/gen_verifier.pure_code.jsonl').open()]
bykey=collections.defaultdict(list)
for r in rows:bykey[r['scenario'],r['task_idx']].append(r)
dups={k:v for k,v in bykey.items() if len(v)>1}
scenarios={k[0] for k in dups}
schemas={}
for l in (root/'data/AgentWorldModel-1K/gen_db.jsonl').open():
 r=json.loads(l)
 if r['scenario'] in scenarios:schemas[r['scenario']]=r
samples={}
for l in (root/'data/AgentWorldModel-1K/gen_sample.jsonl').open():
 r=json.loads(l)
 if r['scenario'] in scenarios:samples[r['scenario']]=r
with tempfile.TemporaryDirectory(prefix='.rule-check-',dir=root) as d:
 for scenario in scenarios:
  p=pathlib.Path(d)/(scenario+'.db');conn=sqlite3.connect(p)
  for t in schemas[scenario]['db_schema']['tables']:
   try:
    conn.execute(t['ddl'])
    for q in t.get('indexes',[]):conn.execute(q)
    for q in t.get('examples',[]):conn.execute(q)
   except sqlite3.Error:pass
  conn.commit();conn.execute('PRAGMA foreign_keys = ON')
  for t in samples[scenario]['sample_data']['tables']:
   for q in t['insert_statements']:
    try:conn.execute(q)
    except sqlite3.Error:pass
  conn.commit()
  for k,v in dups.items():
   if k[0]!=scenario:continue
   for which,r in [('first',v[0]),('latest',v[-1])]:
